/* DM Group IT Renewals Command Center - ERPNext v14 Custom HTML Block (read-only) */
(function () {
  const ROOT = (typeof root_element!=='undefined'&&root_element.querySelector('#dm-it-renewals'))||document.getElementById('dm-it-renewals');
  if (!ROOT) return;
  if (ROOT.__dmrInit) return; ROOT.__dmrInit = true;
  const $ = s => ROOT.querySelector(s);
  const esc = v => String(v == null ? '' : v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const DOCTYPE = 'IT Renewals Subscription';
  const tabs = ['overview','register','calendar','finance','vendors','actions'];
  const tr = {
    en:{subtitle:'Platforms & Renewals Command Center',title:'IT Platforms & Renewals',tagline:'Subscription portfolio · Expiry intelligence · Cost governance',overview:'Overview',register:'Subscriptions',calendar:'Expiry Calendar',finance:'Financial Analysis',vendors:'Vendors',actions:'Renewal Actions',all:'All statuses',expired:'Expired',today:'Due today',d7:'Next 7 days',d30:'Next 30 days',d90:'Next 90 days',active:'Active',unknown:'Missing expiry',allcats:'All categories',search:'Search subscriptions, providers...',refresh:'↻ Refresh',loading:'Loading subscriptions from ERPNext…',noresults:'No matching subscriptions.',total:'Total subscriptions',next:'Next renewals',titleOverview:'Executive Overview',titleRegister:'Subscription Register',titleCalendar:'Expiry Calendar',titleFinance:'Financial Analysis',titleVendors:'Vendor Portfolio',titleActions:'Renewal Action Center',readOnly:'Read-only ERP data',status:'Status',name:'Subscription',provider:'Provider',category:'Category',expiry:'Expiry date',days:'Remaining days',amount:'Recorded amount',period:'Renewal period',notes:'Remarks',open:'Open ERP record ↗',close:'Close',records:'records',month:'Month',none:'No renewals in this month.',detail:'Subscription details',moneyNote:'Recorded source amounts, separated by currency. Monthly and yearly charges are not combined into an annualized budget.',focus:'Immediate attention',actionNote:'Read-only recommendations; no task or payment has been created.',source:'Live subscriptions',missing:'Missing expiry dates',further:'Beyond 90 days'},
    ar:{subtitle:'مركز إدارة المنصات والتجديدات',title:'منصات وتجديدات تقنية المعلومات',tagline:'الاشتراكات · مراقبة تواريخ الانتهاء · إدارة التكاليف',overview:'نظرة عامة',register:'الاشتراكات',calendar:'تقويم الانتهاء',finance:'التحليل المالي',vendors:'الموردون',actions:'إجراءات التجديد',all:'كل الحالات',expired:'منتهي',today:'ينتهي اليوم',d7:'خلال ٧ أيام',d30:'خلال ٣٠ يوماً',d90:'خلال ٩٠ يوماً',active:'ساري',unknown:'بدون تاريخ انتهاء',allcats:'كل الفئات',search:'ابحث عن الاشتراكات والموردين...',refresh:'↻ تحديث',loading:'جاري تحميل الاشتراكات من النظام…',noresults:'لا توجد اشتراكات مطابقة.',total:'إجمالي الاشتراكات',next:'التجديدات القادمة',titleOverview:'نظرة تنفيذية عامة',titleRegister:'سجل الاشتراكات',titleCalendar:'تقويم الانتهاء',titleFinance:'التحليل المالي',titleVendors:'الموردون',titleActions:'إجراءات التجديد',readOnly:'بيانات للعرض فقط من النظام',status:'الحالة',name:'الاشتراك',provider:'المورد',category:'الفئة',expiry:'تاريخ الانتهاء',days:'الأيام المتبقية',amount:'المبلغ المسجل',period:'دورية التجديد',notes:'ملاحظات',open:'فتح السجل في النظام ↗',close:'إغلاق',records:'سجل',month:'الشهر',none:'لا توجد تجديدات في هذا الشهر.',detail:'تفاصيل الاشتراك',moneyNote:'المبالغ المسجلة حسب العملة؛ لا يتم جمع التكاليف الشهرية والسنوية كميزانية سنوية.',focus:'تحتاج اهتماماً فورياً',actionNote:'اقتراحات للمتابعة فقط؛ لم يتم إنشاء مهام أو دفعات.',source:'الاشتراكات المباشرة',missing:'تواريخ انتهاء مفقودة',further:'بعد ٩٠ يوماً'}
  };
  const s = {lang:'en',tab:'overview',rows:[],fields:{},error:'',search:'',status:'all',category:'all',selected:null,month:(()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');})(),loading:false,loaded:false};
  const T = key => tr[s.lang][key] || key;
  const todayUTC = () => { const d=new Date();return Date.UTC(d.getFullYear(),d.getMonth(),d.getDate()); };
  const dayNum = date => {if(!date)return null;const m=String(date).match(/^(\d{4})-(\d{2})-(\d{2})/);if(!m)return null;return Math.round((Date.UTC(+m[1],+m[2]-1,+m[3])-todayUTC())/86400000);};
  const num = n => Number(n)||0;
  const pretty = n => new Intl.NumberFormat(s.lang==='ar'?'ar-SA':'en-US',{maximumFractionDigits:2}).format(num(n));
  function urgency(r){const n=dayNum(r.expiry);if(n===null)return 'unknown';if(n<0)return 'expired';if(n===0)return 'today';if(n<=7)return 'd7';if(n<=30)return 'd30';if(n<=90)return 'd90';return 'active';}
  function label(r){const n=dayNum(r.expiry);return n===null?T('unknown'):n<0?T('expired')+' ('+Math.abs(n)+'d)':n===0?T('today'):n<=7?T('d7')+' ('+n+'d)':n<=30?T('d30')+' ('+n+'d)':n<=90?T('d90')+' ('+n+'d)':T('active');}
  function badge(r){const z=urgency(r),cl=z==='expired'?'expired':z==='unknown'?'unknown':z==='active'?'good':'soon';return '<span class="dmr-pill '+cl+'">'+esc(label(r))+'</span>';}
  function nav(){ $('#dmr-nav').innerHTML=tabs.map(k=>'<button type="button" data-tab="'+k+'" class="'+(k===s.tab?'active':'')+'">'+T(k)+'</button>').join(''); }
  function applyLang(){ROOT.setAttribute('dir',s.lang==='ar'?'rtl':'ltr');ROOT.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=T(el.getAttribute('data-i18n')));$('#dmr-language').textContent=s.lang==='en'?'العربية':'English';$('#dmr-refresh').textContent=T('refresh');$('#dmr-search').placeholder=T('search');$('#dmr-footer-note').textContent=T('readOnly');}
  function filters(){const options=[['all','all'],['expired','expired'],['today','today'],['d7','d7'],['d30','d30'],['d90','d90'],['active','active'],['unknown','unknown']];$('#dmr-filter-status').innerHTML=options.map(([id,label])=>'<option value="'+id+'">'+T(label)+'</option>').join('');$('#dmr-filter-status').value=s.status;const cats=[...new Set(s.rows.map(x=>x.category).filter(Boolean))].sort();$('#dmr-filter-category').innerHTML='<option value="all">'+T('allcats')+'</option>'+cats.map(c=>'<option value="'+esc(c)+'">'+esc(c)+'</option>').join('');$('#dmr-filter-category').value=s.category;}
  const cand={name:['name'],expiry:['expiry_date','expiry','end_date','valid_till','renewal_date','subscription_expiry','expiration_date','date_of_expiry'],next:['next_renewal','next_renewal_date','renewal_date','next_renewal_due'],amount:['total_amount','amount','renewal_amount','cost','subscription_amount','annual_cost','price'],currency:['currency','currency_code'],provider:['provider__source','provider_source','provider','source','service_provider','vendor','supplier','type_of_renewal'],period:['renewal_period','renewal_frequency','billing_cycle','frequency','renewal_type'],category:['type_renewal','category','subscription_category','platform_type','type_of_renewal'],remarks:['remarks','description','notes','remark'],company:['company'],status:['status']};
  function pick(meta){const names=new Set((meta.fields||[]).map(f=>f.fieldname));const out={};for(const [k,choices] of Object.entries(cand)){out[k]=choices.find(c=>names.has(c))||null;}out.name='name';return out;}
  function normalize(raw,f){const v=k=>f[k]?raw[f[k]]:null;const name=String(raw.name||'');let category=String(v('category')||'').trim();const text=(name+' '+(v('provider')||'')+' '+category).toLowerCase();if(!category||category===String(v('provider')||'')){category=/domain|\.com|\.sa|\.net|\.ai/.test(text)?'Domains':/vps|hosting|server|cpanel/.test(text)?'Hosting':/stc|zain|mobily|landline|router|topnet|internet|connection/.test(text)?'Telecom':/erp|microsoft|zoom|canva|autocad|apple|office|software/.test(text)?'Software':'Other';}
    return {id:String(raw.name||''),name,expiry:String(v('expiry')||'').slice(0,10),next:String(v('next')||'').slice(0,10),amount:num(v('amount')),currency:String(v('currency')||'Unspecified'),provider:String(v('provider')||'—'),period:String(v('period')||'—'),category,remarks:String(v('remarks')||''),company:String(v('company')||''),docstatus:raw.docstatus,status:String(v('status')||'')};}
  function frappeCall(method,args){return new Promise((resolve,reject)=>{if(!window.frappe||!frappe.call){reject(new Error('Open this dashboard inside an authenticated ERPNext Desk page.'));return;}try{frappe.call({method,args,callback:r=>r&&r.exc?reject(new Error('ERP rejected the data request. Check role and DocType read permissions.')):resolve(r&&r.message!==undefined?r.message:r),error:e=>reject(new Error(e&&e.message||'ERP request failed'))});}catch(e){reject(e);}});}
  async function metadata(){if(frappe.model&&frappe.model.with_doctype){await new Promise((resolve,reject)=>{try{frappe.model.with_doctype(DOCTYPE,()=>resolve());}catch(e){reject(e);}});const meta=frappe.get_meta(DOCTYPE);if(meta&&meta.fields)return meta;}const r=await frappeCall('frappe.client.get_meta',{doctype:DOCTYPE});return r;}
  async function load(){s.loading=true;s.error='';render();try{const meta=await metadata();const fields=pick(meta);s.fields=fields;if(!fields.expiry)throw new Error('Could not identify the expiry-date field in IT Renewals Subscription. Check the DocType fieldname and add it to the dashboard expiry mapping.');const use=['name','docstatus',...Object.values(fields).filter(Boolean)];const uniq=[...new Set(use)];let items=[],start=0;for(let page=0;page<100;page++){const batch=await frappeCall('frappe.client.get_list',{doctype:DOCTYPE,fields:uniq,limit_start:start,limit_page_length:100,order_by:'modified desc'});if(!Array.isArray(batch))throw new Error('Unexpected response from ERP subscription list.');items.push(...batch);start+=batch.length;if(batch.length<100)break;}s.rows=items.filter(r=>r.docstatus!==2).map(r=>normalize(r,fields));s.loaded=true;if(!fields.amount||!fields.currency){s.error='Financial totals are incomplete: '+(!fields.amount?'amount ':'')+(!fields.currency?'currency':'')+' field could not be mapped. Inspect DocType fields before relying on financial cards.';} }catch(e){s.error=String(e.message||e);s.rows=[];s.loaded=false;}finally{s.loading=false;render();}}
  const filtered=()=>s.rows.filter(r=>(s.status==='all'||urgency(r)===s.status)&&(s.category==='all'||r.category===s.category)&&((r.name+' '+r.provider+' '+r.company).toLowerCase().includes(s.search.toLowerCase())));
  const sorted=rows=>rows.slice().sort((a,b)=>(a.expiry||'9999').localeCompare(b.expiry||'9999'));
  const rowHtml=r=>'<tr data-doc="'+esc(r.id)+'" data-id="'+esc(r.id)+'" title="'+esc(T('open'))+'"><td><strong>'+esc(r.name)+'</strong><br><small>'+esc(r.provider)+'</small></td><td>'+esc(r.category)+'</td><td>'+esc(r.expiry||'—')+'</td><td>'+badge(r)+'</td><td>'+esc(pretty(r.amount))+' '+esc(r.currency)+'</td></tr>';
  function detail(r){return '<section class="dmr-details"><div class="dmr-row"><h3>'+T('detail')+'</h3><button data-action="close">'+T('close')+'</button></div><h3>'+esc(r.name)+'</h3><dl>'+[['provider',r.provider],['category',r.category],['expiry',r.expiry||'—'],['days',dayNum(r.expiry)??'—'],['amount',pretty(r.amount)+' '+r.currency],['period',r.period],['notes',r.remarks||'—'],['Company',r.company||'—'],['Next renewal',r.next||'—'],['status',r.status||'—']].map(([k,v])=>'<div><dt>'+esc(T(k))+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl><div class="dmr-actions"><button data-action="open" data-id="'+esc(r.name)+'">'+T('open')+'</button></div></section>';}
  function overview(){const all=s.rows, counts={expired:0,today:0,d7:0,d30:0,d90:0,active:0,unknown:0};all.forEach(r=>counts[urgency(r)]++);const kpis=[['all',T('total'),all.length,T('source')],['expired',T('expired'),counts.expired,T('focus')],['today',T('today'),counts.today,T('focus')],['d30',T('d30'),counts.d7+counts.d30,T('next')],['unknown',T('missing'),counts.unknown,T('missing')]];const critical=sorted(all.filter(r=>['expired','today','d7','d30'].includes(urgency(r)))).slice(0,8);return '<div class="dmr-kpis">'+kpis.map(([f,l,n,sub])=>'<button class="dmr-card dmr-kpi" data-filter="'+f+'"><div class="dmr-kpi-label">'+l+'</div><div class="dmr-kpi-num '+(f==='expired'?'dmr-danger':f==='today'?'dmr-warning':'')+'">'+pretty(n)+'</div><div class="dmr-kpi-foot">'+sub+' ↗</div></button>').join('')+'</div><div class="dmr-grid"><section class="dmr-card"><h3>Expiry distribution</h3>'+Object.entries(counts).map(([k,n])=>'<div class="dmr-bar-line"><div class="dmr-bar-head"><span>'+T(k)+'</span><b>'+pretty(n)+'</b></div><div class="dmr-track"><div class="dmr-fill '+(k==='expired'?'expired':k==='active'?'good':'soon')+'" style="width:'+(all.length?n/all.length*100:0)+'%"></div></div></div>').join('')+'</section><section class="dmr-card"><h3>'+T('focus')+'</h3>'+(critical.length?critical.map(r=>'<div class="dmr-row"><div><strong>'+esc(r.name)+'</strong><small>'+esc(r.expiry||'—')+' · '+esc(r.provider)+'</small></div>'+badge(r)+'</div>').join(''):'<p class="dmr-muted">'+T('noresults')+'</p>')+'</section></div><section class="dmr-card"><h3>'+T('next')+'</h3>'+table(sorted(all).slice(0,10))+'</section>';}
  function table(rows){return '<div class="dmr-table-wrap"><table><thead><tr>'+['name','category','expiry','status','amount'].map(k=>'<th>'+T(k)+'</th>').join('')+'</tr></thead><tbody>'+(rows.length?rows.map(rowHtml).join(''):'<tr><td colspan="5" class="dmr-empty">'+T('noresults')+'</td></tr>')+'</tbody></table></div>';}
  function register(){return '<section class="dmr-card"><h3>'+pretty(filtered().length)+' '+T('records')+'</h3>'+table(sorted(filtered()))+(s.selected&&s.rows.find(r=>r.name===s.selected)?detail(s.rows.find(r=>r.name===s.selected)):'')+'</section>';}
  function calendar(){const y=+s.month.slice(0,4),m=+s.month.slice(5,7),start=new Date(y,m-1,1).getDay(),length=new Date(y,m,0).getDate(),e=filtered().filter(r=>r.expiry.startsWith(s.month));let cells=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>'<div class="dmr-weekday">'+d+'</div>').join('');cells+='<div></div>'.repeat(start);for(let day=1;day<=length;day++){const date=s.month+'-'+String(day).padStart(2,'0'),events=e.filter(r=>r.expiry===date);cells+='<div class="dmr-day '+(events.length?'event':'')+'"><strong>'+day+'</strong>'+events.map(r=>'<div class="dmr-event" title="'+esc(r.name)+'" data-id="'+esc(r.name)+'">● '+esc(r.name)+'</div>').join('')+'</div>';}return '<section class="dmr-card"><div class="dmr-cal-head"><h3>'+T('calendar')+'</h3><input id="dmr-month" type="month" value="'+s.month+'"/></div><div class="dmr-calendar">'+cells+'</div><h3 style="margin-top:22px">'+pretty(e.length)+' '+T('records')+'</h3>'+e.map(r=>'<div class="dmr-row" data-id="'+esc(r.name)+'"><div><strong>'+esc(r.name)+'</strong><small>'+esc(r.vendor||r.provider)+'</small></div><span>'+esc(r.expiry)+'</span></div>').join('')+(e.length?'':'<p class="dmr-muted">'+T('none')+'</p>')+(s.selected&&s.rows.find(r=>r.name===s.selected)?detail(s.rows.find(r=>r.name===s.selected)):'')+'</section>';}
  function finance(){const groups={};filtered().forEach(r=>{const c=r.currency||'Unspecified';(groups[c]||(groups[c]=[])).push(r);});const cur=Object.keys(groups).sort();return '<p class="dmr-muted">'+T('moneyNote')+'</p><div class="dmr-kpis">'+cur.map(c=>'<div class="dmr-card"><div class="dmr-kpi-label">'+esc(c)+'</div><div class="dmr-kpi-num">'+pretty(groups[c].reduce((a,b)=>a+b.amount,0))+'</div><div class="dmr-kpi-foot">'+groups[c].length+' '+T('records')+'</div></div>').join('')+'</div><section class="dmr-card"><h3>Recorded cost by currency / category</h3>'+cur.map(c=>{const cat={};groups[c].forEach(r=>cat[r.category]=(cat[r.category]||0)+r.amount);const max=Math.max(1,...Object.values(cat));return '<h3>'+esc(c)+'</h3>'+Object.entries(cat).sort((a,b)=>b[1]-a[1]).map(([k,v])=>'<div class="dmr-bar-line"><div class="dmr-bar-head"><span>'+esc(k)+'</span><b>'+pretty(v)+' '+esc(c)+'</b></div><div class="dmr-track"><div class="dmr-fill" style="width:'+(v/max*100)+'%"></div></div></div>').join('');}).join('')+'</section>';}
  function vendors(){const vendors={};filtered().forEach(r=>(vendors[r.provider]||(vendors[r.provider]=[])).push(r));return '<div class="dmr-vendors">'+Object.entries(vendors).sort((a,b)=>b[1].length-a[1].length).map(([name,items])=>'<button class="dmr-card dmr-vendor" data-vendor="'+esc(name)+'"><strong>'+esc(name)+'</strong><div class="dmr-metric">'+pretty(items.length)+'</div><small>'+[...new Set(items.map(x=>x.category))].join(' · ')+'</small><p class="dmr-muted">View records ↗</p></button>').join('')+'</div>'+(Object.keys(vendors).length?'':'<div class="dmr-card dmr-empty">'+T('noresults')+'</div>');}
  function actions(){const cases=[['expired','Past-due renewals','Verify actual renewal, payment and updated expiry dates.'],['today','Due today','Confirm service continuity and vendor renewal.'],['d7','Next 7 days','Prepare approvals and payment arrangements.'],['d30','Next 30 days','Validate upcoming charges, ownership and budget.'],['unknown','Missing expiry information','Correct records before relying on automated alerts.']];return '<p class="dmr-muted">'+T('actionNote')+'</p>'+cases.map(([f,name,desc])=>{const rs=s.rows.filter(r=>urgency(r)===f);return '<section class="dmr-card" style="margin-bottom:12px"><div class="dmr-row"><div><h3>'+esc(name)+'</h3><p class="dmr-muted">'+esc(desc)+'</p><small>'+pretty(rs.length)+' '+T('records')+'</small></div><button data-filter="'+f+'">View →</button></div>'+rs.slice(0,5).map(r=>'<div class="dmr-row" data-id="'+esc(r.name)+'"><div><strong>'+esc(r.name)+'</strong><small>'+esc(r.expiry||'—')+'</small></div>'+badge(r)+'</div>').join('')+'</section>';}).join('');}
  function render(){applyLang();nav();filters();$('#dmr-search').value=s.search;$('#dmr-view-title').textContent=T('title'+s.tab[0].toUpperCase()+s.tab.slice(1));$('#dmr-view-caption').textContent=s.rows.length+' '+T('records');$('#dmr-asof').textContent=new Date().toLocaleDateString(s.lang==='ar'?'ar-SA':'en-GB',{day:'2-digit',month:'short',year:'numeric'});$('#dmr-source').textContent=s.loaded?'ERP LIVE':'ERP';$('#dmr-notice').hidden=!s.error;$('#dmr-notice').textContent=s.error||'';$('#dmr-content').innerHTML=s.loading?'<div class="dmr-loading">'+T('loading')+'</div>':!s.loaded?'<div class="dmr-loading">'+esc(s.error||'No data loaded')+'</div>':({overview,register,calendar,finance,vendors,actions}[s.tab])();}
  ROOT.addEventListener('click',e=>{const b=e.target.closest('[data-tab],[data-filter],[data-vendor],[data-action],[data-doc],[data-id]');if(!b||!ROOT.contains(b))return;if(b.dataset.tab){s.tab=b.dataset.tab;s.selected=null;}else if(b.dataset.filter){s.tab='register';s.status=b.dataset.filter;s.selected=null;}else if(b.dataset.vendor){s.tab='register';s.status='all';s.search=b.dataset.vendor;s.selected=null;}else if(b.dataset.action==='close')s.selected=null;else if(b.dataset.action==='open'){window.open('/app/it-renewals-subscription/'+encodeURIComponent(b.dataset.id),'_blank','noopener');return;}else if(b.dataset.doc){openDoc(b.dataset.doc);return;}else if(b.dataset.id){s.selected=b.dataset.id;if(s.tab!=='register'&&s.tab!=='calendar')s.tab='register';}render();});
  function openDoc(id){if(!id)return;if(window.frappe&&typeof frappe.set_route==='function'){frappe.set_route('Form',DOCTYPE,id);}else{window.location.href='/app/it-renewals-subscription/'+encodeURIComponent(id);}}
  $('#dmr-language').addEventListener('click',()=>{s.lang=s.lang==='en'?'ar':'en';render();});
  $('#dmr-refresh').addEventListener('click',load);
  $('#dmr-filter-status').addEventListener('change',e=>{s.status=e.target.value;s.selected=null;render();});
  $('#dmr-filter-category').addEventListener('change',e=>{s.category=e.target.value;s.selected=null;render();});
  $('#dmr-search').addEventListener('input',e=>{const val=e.target.value;s.search=val;const start=e.target.selectionStart;render();$('#dmr-search').focus();$('#dmr-search').setSelectionRange(start,start);});
  ROOT.addEventListener('change',e=>{if(e.target.id==='dmr-month'){s.month=e.target.value;s.selected=null;render();}});
  load();
})();

