-it-renewals .dmr-row:last-child{border:0}#dm-it-renewals .dmr-row strong{display:block;font-weight:600}#dm-it-renewals .dmr-row small{display:block;margin-top:4px}#dm-it-renewals .dmr-pill{display:inline-block;border-radius:20px;padding:5px 9px;background:#eef3f8;color:#42607b;font-weight:600;font-size:10px;white-space:nowrap}#dm-it-renewals .dmr-pill.expired{background:#fce8e8;color:#b83f42}#dm-it-renewals .dmr-pill.soon{background:#fff1d8;color:#94610f}#dm-it-renewals .dmr-pill.good{background:#e3f4ef;color:#16735f}#dm-it-renewals .dmr-pill.unknown{background:#edf0f4;color:#5e6879}#dm-it-renewals .dmr-bar-line{margin-bottom:12px}#dm-it-renewals .dmr-bar-head{display:flex;justify-content:space-between;margin-bottom:6px;font-size:12px}#dm-it-renewals .dmr-track{height:9px;border-radius:20px;background:#edf2f7;overflow:hidden}#dm-it-renewals .dmr-fill{height:100%;border-radius:20px;background:#7295c0}#dm-it-renewals .dmr-fill.expired{background:#d55459}#dm-it-renewals .dmr-fill.soon{background:#e6a54d}#dm-it-renewals .dmr-fill.good{background:#46a58d}#dm-it-renewals .dmr-table-wrap{overflow-x:auto}#dm-it-renewals table{border-collapse:collapse;width:100%;min-width:650px}#dm-it-renewals th{text-align:left;color:#718096;text-transform:uppercase;letter-spacing:.4px;font-size:10px;background:#f8fafc;padding:11px;border-bottom:1px solid var(--line)}#dm-it-renewals td{padding:12px 11px;border-bottom:1px solid #edf1f5;vertical-align:middle}#dm-it-renewals td strong{font-weight:600}#dm-it-renewals tr[data-id]{cursor:pointer}#dm-it-renewals tr[data-id]:hover{background:#f4f8fc}#dm-it-renewals .dmr-footer{margin-top:20px;display:flex;justify-content:space-between;gap:8px;font-size:11px;color:var(--muted)}#dm-it-renewals a{color:#285e9f;text-decoration:none}#dm-it-renewals .dmr-cal-head{display:flex;justify-content:space-between;margin-bottom:15px;align-items:center;gap:8px}#dm-it-renewals .dmr-calendar{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:5px}#dm-it-